mapper.sql:
WITH noticeType AS ( SELECT sys09_code noticeType_cd , sys09_name noticeType_nm FROM sys08_code_kind INNER JOIN sys09_code ON sys09_code_kind_id = sys08_code_kind_id WHERE sys08_kind_cd = 'NoticeType' AND sys09_company_id = CASE WHEN COALESCE(sys08_sys_yn,'false') = 'true' THEN 0 ELSE #{c.companyId} END ), noticeDetail AS ( SELECT sys09_code noticeDetail_cd , sys09_name noticeDetail_nm FROM sys08_code_kind INNER JOIN sys09_code ON sys09_code_kind_id = sys08_code_kind_id WHERE sys08_kind_cd = 'NoticeDetailCode' AND sys09_company_id = CASE WHEN COALESCE(sys08_sys_yn,'false') = 'true' THEN 0 ELSE #{c.companyId} END ), bbs AS ( SELECT t.* FROM ( SELECT bbs02_notice.* , noticeType_nm AS bbs02_notice_type_nm , noticeDetail_nm AS bbs02_notice_detail_nm , ( CASE WHEN COALESCE(bbs02_top_notice_yn, 'false') = 'true' THEN CASE WHEN f_today() <= bbs02_top_notice_close_date THEN 'true' ELSE 'false' END ELSE 'false' END ) AS bbs02_top_yn FROM bbs02_notice LEFT OUTER JOIN noticeType ON noticeType_cd = bbs02_notice_type LEFT OUTER JOIN noticeDetail ON noticeDetail_cd = bbs02_notice_detail_cd WHERE bbs02_company_id = #{c.companyId} AND bbs02_notice_type LIKE #{c.noticeType} AND COALESCE(bbs02_notice_detail_cd,'') LIKE #{c.noticeDetail} AND bbs02_notice_type IN ( SELECT sys09_code FROM sys13_code_group INNER JOIN sys09_code ON sys09_code_id = sys13_code_id WHERE sys13_kind_group_cd = #{c.typeCode} ) ) t WHERE 1=1
AND ( ( bbs02_top_yn = 'false' AND bbs02_from_date BETWEEN #{c.startDate}::date AND #{c.closeDate}::date ) OR ( bbs02_top_yn != 'false' ) )
)

mapper.select:

SELECT 
  FROM bbs
 WHERE UPPER(CONCAT(bbs02_notice_type_nm, bbs02_notice_detail_nm, bbs02_title, bbs02_note)) LIKE UPPER(#{c.searchText})
   AND bbs02_open_yn LIKE #{c.openYn}
 ORDER BY bbs02_from_date DESC, bbs02_notice_id DESC
 LIMIT #{c.limit}
OFFSET #{c.offset}

SELECT bbs02_notice_no
  FROM bbs02_notice
 WHERE bbs02_notice_id = #{noticeId}

mapper.delete:
DELETE FROM bbs02_notice
 WHERE bbs02_notice_id  = #{noticeId}
   AND bbs02_company_id = #{companyId}

DELETE FROM bbs04_target_company
 WHERE bbs04_notice_id = #{noticeId}
   AND bbs04_target_company_id IN
#{id}
